import{_ as t,o,c as a,ag as i}from"./chunks/framework.B_zcDAFh.js";const g=JSON.parse('{"title":"Boing Bones","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boing-bones.md","filePath":"guide/boing-bones.md"}'),n={name:"guide/boing-bones.md"};function r(s,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="boing-bones" tabindex="-1">Boing Bones <a class="header-anchor" href="#boing-bones" aria-label="Permalink to &quot;Boing Bones&quot;">​</a></h1><p>The <strong>Boing Bones</strong> component creates bouncy hierarchies of skeletal bones or plain transforms. Use it for hair, tails, antennae, jiggly props, jellyfish tentacles — anything where motion should propagate down a chain.</p><h2 id="setting-up-a-chain" tabindex="-1">Setting Up a Chain <a class="header-anchor" href="#setting-up-a-chain" aria-label="Permalink to &quot;Setting Up a Chain&quot;">​</a></h2><ol><li>Add <code>BoingBones</code> to a GameObject.</li><li>Specify the <strong>root transform</strong> of a bone chain. The bouncy effect begins at the root and propagates down through the entire hierarchy beneath it.</li><li>Optionally, add more chains — each <code>BoingBones</code> component supports multiple chains, each with its own root.</li></ol><h2 id="collision" tabindex="-1">Collision <a class="header-anchor" href="#collision" aria-label="Permalink to &quot;Collision&quot;">​</a></h2><p>Boing Bones can react to two kinds of colliders:</p><ul><li><strong>Boing Colliders</strong> — lightweight colliders provided by Boing Kit, added to the <em>Boing Colliders</em> section in the Inspector. Cheaper than Unity&#39;s physics colliders; preferred for in-chain collision.</li><li><strong>Unity Colliders</strong> — standard Unity colliders, added to the <em>Unity Collider</em> section. Useful when you want bones to collide against existing physics geometry.</li></ul><h2 id="effector-reactivity" tabindex="-1">Effector Reactivity <a class="header-anchor" href="#effector-reactivity" aria-label="Permalink to &quot;Effector Reactivity&quot;">​</a></h2><p>Boing Bones also react to <a href="./boing-effector.html">Boing Effectors</a>, just like <a href="./boing-reactor.html">Boing Reactors</a> do — so wind, explosions, or player proximity can disturb a bone chain naturally.</p><h2 id="avoiding-sudden-jumps-after-teleports" tabindex="-1">Avoiding Sudden Jumps After Teleports <a class="header-anchor" href="#avoiding-sudden-jumps-after-teleports" aria-label="Permalink to &quot;Avoiding Sudden Jumps After Teleports&quot;">​</a></h2><p>After teleporting a rig, call <code>BoingBones.HandleTeleport()</code> to reset the chain&#39;s internal state. Otherwise the chain interprets the teleport as a high-velocity displacement and snaps wildly on the next <code>LateUpdate</code>.</p><h2 id="twist-propagation" tabindex="-1">Twist Propagation <a class="header-anchor" href="#twist-propagation" aria-label="Permalink to &quot;Twist Propagation&quot;">​</a></h2><p>Twist propagation lets axial rotation travel down the chain. For chains created with newer versions of Boing Kit this is on by default; older chains keep the legacy behavior for backward compatibility. Twist propagation uses swing-twist decomposition to avoid rotational drift.</p><h2 id="update-order-with-other-procedural-animation" tabindex="-1">Update Order with Other Procedural Animation <a class="header-anchor" href="#update-order-with-other-procedural-animation" aria-label="Permalink to &quot;Update Order with Other Procedural Animation&quot;">​</a></h2><p>Boing Bones runs during <code>LateUpdate</code>. If you use other procedural-animation assets (IK solvers, secondary motion), they also typically run in <code>LateUpdate</code> and Unity doesn&#39;t guarantee an order. Boing Kit must run <strong>last</strong>. Set this via <strong>Edit &gt; Project Settings &gt; Script Execution Order</strong> — see the <a href="./faq.html">FAQ</a> for details.</p><p>See the <a href="/boing-kit/gallery/boing-bones.html">Boing Bones gallery</a> for example scenes and the <a href="/boing-kit/api/boing-bones.html">API reference</a> for the full property list.</p>',16)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
